private static void assertAggOfConstExprs(AggOfLiteralTestCase testCase, List<Alias> exprs) {
        var s = as(exprs.get(0), Alias.class);
        assertThat(s.source().toString(), containsString(LoggerMessageFormat.format(null, testCase.aggFunctionTemplate, "[1,2]")));
        assertEquals(s.child(), testCase.replacementForConstant.apply(new Literal(EMPTY, List.of(1, 2), INTEGER)));
        assertEquals(s.child().fold(), testCase.aggMultiValue.apply(new int[] { 1, 2 }));

        var s_expr = as(exprs.get(1), Alias.class);
        assertThat(s_expr.source().toString(), containsString(LoggerMessageFormat.format(null, testCase.aggFunctionTemplate, "314.0/100")));
        assertEquals(
            s_expr.child(),
            testCase.replacementForConstant.apply(new Div(EMPTY, new Literal(EMPTY, 314.0, DOUBLE), new Literal(EMPTY, 100, INTEGER)))
        );
        assertEquals(s_expr.child().fold(), testCase.aggSingleValue.apply(3.14));

        var s_null = as(exprs.get(2), Alias.class);
        assertThat(s_null.source().toString(), containsString(LoggerMessageFormat.format(null, testCase.aggFunctionTemplate, "null")));
        assertEquals(s_null.child(), testCase.replacementForConstant.apply(NULL));
        // Cannot just fold as there may be no evaluator for the NULL datatype;
        // instead we emulate how the optimizer would fold the null value:
        // it transforms up from the leaves; c.f. FoldNull.
        assertTrue(oneLeaveIsNull(s_null));
    }

private static List<Expression> combineUpperGroupingsAndLowerProjections(
            List<? extends Expression> upperGroupings,
            List<? extends NamedExpression> lowerProjections
        ) {
            // Collect the alias map for resolving the source (f1 = 1, f2 = f1, etc..)
            AttributeMap<Expression> aliases = new AttributeMap<>();
            for (NamedExpression ne : lowerProjections) {
                // record the alias
                aliases.put(ne.toAttribute(), Alias.unwrap(ne));
            }

            // Replace any matching attribute directly with the aliased attribute from the projection.
            AttributeSet replaced = new AttributeSet();
            for (Expression expr : upperGroupings) {
                // All substitutions happen before; groupings must be attributes at this point.
                Attribute attr = (Attribute) expr;
                replaced.add((Attribute) aliases.resolve(attr, attr));
            }
            return replaced.stream().map(attr -> (Expression) attr).toList();
        }

@Override
    public Expression surrogate() {
        var s = source();
        var field = field();

        if (field.foldable()) {
            if (field instanceof Literal l) {
                if (l.value() != null && (l.value() instanceof List<?>) == false) {
                    // TODO: Normalize COUNT(*), COUNT(), COUNT("foobar"), COUNT(1) as COUNT(*).
                    // Does not apply to COUNT([1,2,3])
                    // return new Count(s, new Literal(s, StringUtils.WILDCARD, DataTypes.KEYWORD));
                    return null;
                }
            }

            // COUNT(const) is equivalent to MV_COUNT(const)*COUNT(*) if const is not null; otherwise COUNT(const) == 0.
            return new Mul(
                s,
                new Coalesce(s, new MvCount(s, field), List.of(new Literal(s, 0, DataTypes.INTEGER))),
                new Count(s, new Literal(s, StringUtils.WILDCARD, DataTypes.KEYWORD))
            );
        }

        return null;
    }

@Override
    public Expression surrogate() {
        var s = source();
        var field = field();

        return field.foldable()
            ? new ToLong(s, new Coalesce(s, new MvCount(s, new MvDedupe(s, field)), List.of(new Literal(s, 0, DataTypes.INTEGER))))
            : null;
    }
